-- Patron para evitar deadlocks:
-- Siempre acceder a tablas en el mismo orden
-- Transaccion 1: tabla A primero, luego B
-- Transaccion 2: tabla A primero, luego B

try (Connection c = ds.getConnection()) {
  c.setAutoCommit(false);
  try (PreparedStatement ps1 = c.prepareStatement(
        "UPDATE cuentas SET saldo = saldo - ? WHERE id = ?")) {
    ps1.setDouble(1, 100);
    ps1.setInt(2, 1);
    ps1.executeUpdate();
  }
  try (PreparedStatement ps2 = c.prepareStatement(
        "UPDATE cuentas SET saldo = saldo + ? WHERE id = ?")) {
    ps2.setDouble(1, 100);
    ps2.setInt(2, 2);
    ps2.executeUpdate();
  }
  c.commit();
} catch (SQLException e) {
  if (c != null) {
    try { c.rollback(); } catch (SQLException ex) { /* log */ }
  }
  throw e;
}

